      "examples": [
        {
          "de": "Die Zeit ist knapp.",
          "lv": "Времето е малко."
        },
        {
          "de": "Das Geld wird knapp.",
          "lv": "Парите свършват."
        },
        {
          "de": "Er hat knapp gewonnen.",
          "lv": "Той спечели с малка разлика."
        }
      ],
      "comparison": [
        {
          "word": "knapp",
          "meaning": "Малко/едва/с малка разлика",
          "example": "Die Zeit ist knapp. = Времето е малко."
        },
        {
          "word": "eng",
          "meaning": "Тесен/тясно",
          "example": "Der Raum ist eng. = Стаята е тясна."
        },
        {
          "word": "kurz",
          "meaning": "Кратко",
          "example": "Die Antwort ist kurz. = Отговорът е кратък."
        }
      ],
      "tip": {
        "leftBlocks": [
          {
            "text": "Knapp означава: достатъчно, но не достатъчно."
          }
        ]
      },
      "important": {
        "text": "Knapp не е малък. Това показва малък марж, недостатък или много малко предимство."
      },
